//! Styles of text generated by a test.

use text_mesh_core::{Color, FontWeight, Style};

/// Creates plain `color` text at `size` without decorations, offsets, rotation, or font/material overrides.
#[must_use]
pub const fn plain(color: Color, size: f32) -> Style {
    Style {
        color,
        bold: false,
        weight: FontWeight::REGULAR,
        italic: false,
        underline: None,
        strikethrough: None,
        highlight: None,
        size,
        subscript: false,
        superscript: false,
        small_caps: false,
        character_spacing: 0.0,
        mono_spacing: 0.0,
        vertical_offset: 0.0,
        rotation: 0.0,
        scale: 1.0,
        font: None,
        material: None,
    }
}
